const input = $input.first().json;
const body = input.body || input;
const eventType = body.event || body.payload?.event_type || '';
const payload = body.payload || body;
const scheduledEvent = payload.scheduled_event || payload.event || {};
const invitee = payload.invitee || payload;
const eventName = (scheduledEvent.name || payload.event_name || '').toString();
const eventUri = (scheduledEvent.uri || payload.event_uri || '').toString();
const slugText = `${eventName} ${eventUri}`.toLowerCase();
if (!slugText.includes('revenue leak audit') && !slugText.includes('revenue-leak-audit')) {
  return [{ json: { ignored: true, reason: 'Not Revenue Leak Audit', eventType, raw: body } }];
}
const email = (invitee.email || payload.email || '').trim().toLowerCase();
const fullName = (invitee.name || payload.name || '').trim();
const firstName = fullName.split(/\s+/)[0] || 'there';
const questions = invitee.questions_and_answers || payload.questions_and_answers || [];
function answer(label) {
  const row = questions.find(q => (q.question || '').toLowerCase().includes(label));
  return row ? row.answer : '';
}
const start = scheduledEvent.start_time || payload.start_time || invitee.event_start_time;
const end = scheduledEvent.end_time || payload.end_time || invitee.event_end_time;
const startMs = start ? new Date(start).getTime() : NaN;
const nowMs = Date.now();
const meetingLink = invitee.event_guest_link || payload.event_guest_link || scheduledEvent.location?.join_url || scheduledEvent.location?.location || '';
const booking = {
  calendly_event_id: scheduledEvent.uuid || scheduledEvent.uri || eventUri,
  calendly_invitee_id: invitee.uuid || invitee.uri || payload.uri || email,
  first_name: firstName,
  email,
  clinic_name: answer('clinic') || payload.clinic_name || payload.company_name || '',
  event_start_time: start,
  event_end_time: end,
  event_timezone: scheduledEvent.event_timezone || scheduledEvent.timezone || payload.timezone || $env.MEDSPA_BOOKING_TIMEZONE || 'America/Toronto',
  meeting_link: meetingLink,
  status: eventType.includes('canceled') || eventType.includes('cancelled') ? 'cancelled' : 'scheduled',
  raw_payload: body
};
const reminderOffsets = [
  ['confirmation', 0],
  ['three_day', 3 * 24 * 60 * 60 * 1000],
  ['one_day', 24 * 60 * 60 * 1000],
  ['thirty_minute', 30 * 60 * 1000],
  ['fifteen_minute', 15 * 60 * 1000]
];
const reminders = Number.isFinite(startMs) ? reminderOffsets.map(([type, offset]) => {
  const scheduledFor = type === 'confirmation' ? nowMs : startMs - offset;
  const impossible = type !== 'confirmation' && scheduledFor <= nowMs;
  const afterStart = scheduledFor >= startMs;
  return { reminder_type: type, scheduled_for: new Date(scheduledFor).toISOString(), status: impossible || afterStart ? 'skipped' : 'scheduled' };
}) : [];
return [{ json: { ignored: false, eventType, booking, reminders } }];

const original = $('Normalize + Filter Revenue Leak Audit').first().json;
const bookingRows = $input.first().json;
const booking = Array.isArray(bookingRows) ? bookingRows[0] : bookingRows;
if (!booking || !booking.id) throw new Error('Supabase did not return booking id');
if (original.booking.status === 'cancelled') {
  return [{ json: { booking, action: 'cancel', reminders: [] } }];
}
return original.reminders.map(r => ({ json: { booking, action: 'schedule', reminder: { booking_id: booking.id, ...r } } }));

const original = $('Normalize + Filter Revenue Leak Audit').first().json;
const logRows = $input.first().json;
const log = Array.isArray(logRows) ? logRows[0] : logRows;
const b = original.booking;
const type = log.reminder_type;
const subjects = {
  confirmation: 'Your Revenue Leak Audit Is Confirmed',
  three_day: 'Quick note before our audit',
  one_day: "Tomorrow's Revenue Leak Audit",
  thirty_minute: 'Starting in 30 minutes',
  fifteen_minute: 'Starting shortly'
};
const bodyMap = {
  confirmation: `During the 30-minute audit, we will review how new leads are followed up, how consultations are converted, how no-shows are recovered, how past patients are reactivated, and where revenue opportunities may be slipping. This is a working session focused on your current revenue recovery process, not a software demonstration.`,
  three_day: `To make the conversation more useful, it may help to have a rough idea of your monthly lead volume, consultation volume, current follow-up process, no-show recovery process, patient reactivation process, and booking/follow-up system. No preparation is required. Rough answers are enough.`,
  one_day: `Just a quick reminder that your Revenue Leak Audit is scheduled for tomorrow. We will review your current follow-up process, where revenue may be leaking, and what a weekly recovery action list could look like.`,
  thirty_minute: `Your Revenue Leak Audit starts in 30 minutes.`,
  fifteen_minute: `Your Revenue Leak Audit starts in 15 minutes.`
};
const shell = (content) => `<!doctype html><html><body style="margin:0;background:#100b11;font-family:Arial,sans-serif;color:#f8eef3;"><div style="max-width:620px;margin:0 auto;padding:28px;"><div style="border:1px solid #3b2230;background:#171018;border-radius:18px;overflow:hidden;"><div style="padding:22px 24px;border-bottom:1px solid #3b2230;"><strong style="color:#e05691;font-size:18px;">MedSpa Growth Engine</strong><div style="color:#b8a6b0;font-size:12px;margin-top:4px;">Revenue Leak Audit</div></div><div style="padding:26px 24px;color:#f8eef3;line-height:1.65;"><p>Hi ${b.first_name || 'there'},</p><p>${content}</p><div style="background:#211620;border:1px solid #3b2230;border-radius:14px;padding:16px;margin:22px 0;"><div><strong>Date:</strong> ${b.event_start_time || 'See calendar invite'}</div><div><strong>Time:</strong> ${b.event_timezone || 'Your calendar timezone'}</div></div><a href="${b.meeting_link || 'https://calendly.com/medspaagrowth/revenue-leak-audit'}" style="display:inline-block;background:#9d2f5d;color:#fff;text-decoration:none;font-weight:700;padding:12px 18px;border-radius:10px;">Join audit</a><p style="margin-top:24px;">Looking forward to speaking with you.</p><p>- Ishan<br/>MedSpa Growth Engine</p></div><div style="padding:16px 24px;border-top:1px solid #3b2230;color:#9d8a95;font-size:12px;line-height:1.5;">We identify potential revenue leaks and recovery opportunities. We do not guarantee revenue, clients, bookings, or medical outcomes.</div></div></div></body></html>`;
return [{ json: { to: b.email, subject: subjects[type] || 'Revenue Leak Audit Reminder', html: shell(bodyMap[type] || bodyMap.confirmation), text: `${subjects[type]}\n\nHi ${b.first_name || 'there'},\n\n${bodyMap[type] || bodyMap.confirmation}\n\nMeeting link: ${b.meeting_link}\n\n- Ishan\nMedSpa Growth Engine`, log_id: log.id, reminder_type: type, should_send_now: type === 'confirmation' } }];
